-- FALAFEL BATACHANA — PARCEL MODULE — parcel_01b_rollback.sql (GATE 03G, stage S1, rebased on Production)
-- Restores public.parcel_requests_before_write() to the EXACT verified Production source
-- (md5 caecf3a8dfcf97889ba246d77add0fac, length 4862, CRLF).
--
-- REVIEW ONLY — NOT EXECUTED. Run only if parcel_01b must be undone (separate approval).
-- Refuses to run unless the live function is exactly the reviewed parcel_01b version.
--
-- Why hex: this project's SQL channel has converted LF to CRLF before, so a readable body could restore the
-- same logic with a different fingerprint. The original source is embedded as hex (from the verified
-- Production CSV export), decoded inside the transaction, checked against md5 + length BEFORE it is used,
-- and only then passed (as a quoted literal via format(%L), no other dynamic input) to CREATE OR REPLACE.
-- Touches nothing else (no table, policy, grant, trigger or data). OID, owner and privileges are kept.
--
-- Source fingerprints (md5(prosrc), length(prosrc)):
--   BEFORE (parcel_01b): 9da7eec21b14950cfcbe4481ecbddf40 / 5560 (CRLF)  |  bf1d4abc4698dd2213023df069b75255 / 5397 (LF)
--   AFTER  (Production): caecf3a8dfcf97889ba246d77add0fac / 4862  — exact

BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- ─── Preflight: the live function must be exactly the reviewed parcel_01b version ─────────────────────
DO $parcel_01b_rollback_preflight$
DECLARE
  v_count  integer;
  v_oid    oid;
  v_result text;
  v_lang   text;
  v_secdef boolean;
  v_cfg    text[];
  v_md5    text;
  v_len    integer;
BEGIN
  SELECT count(*) INTO v_count
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'parcel_requests_before_write';
  IF v_count <> 1 THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: expected exactly one public.parcel_requests_before_write, found %', v_count;
  END IF;

  SELECT p.oid, pg_get_function_result(p.oid), l.lanname, p.prosecdef, p.proconfig, md5(p.prosrc), length(p.prosrc)
    INTO v_oid, v_result, v_lang, v_secdef, v_cfg, v_md5, v_len
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language l ON l.oid = p.prolang
   WHERE n.nspname = 'public' AND p.proname = 'parcel_requests_before_write';

  IF pg_get_function_identity_arguments(v_oid) <> '' OR v_result <> 'trigger' OR v_lang <> 'plpgsql' THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: unexpected signature / language (args=%, result=%, lang=%)',
      pg_get_function_identity_arguments(v_oid), v_result, v_lang;
  END IF;
  IF v_secdef THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: function is SECURITY DEFINER (expected INVOKER)';
  END IF;
  IF v_cfg IS DISTINCT FROM ARRAY['search_path=""'] THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: unexpected function configuration %', v_cfg;
  END IF;
  IF NOT ((v_md5 = '9da7eec21b14950cfcbe4481ecbddf40' AND v_len = 5560)
          OR (v_md5 = 'bf1d4abc4698dd2213023df069b75255' AND v_len = 5397)) THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: live source is not the reviewed parcel_01b version - nothing to roll back or changed; re-review required (md5 %, length %)', v_md5, v_len;
  END IF;

  -- The existing trigger must keep calling this exact function, enabled, as BEFORE INSERT OR UPDATE ... FOR EACH ROW.
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
     WHERE t.tgrelid = to_regclass('public.parcel_requests')
       AND t.tgname = 'parcel_requests_before_write'
       AND NOT t.tgisinternal
       AND t.tgfoid = v_oid
       AND t.tgenabled <> 'D'
       AND pg_get_triggerdef(t.oid) ILIKE '%BEFORE INSERT OR UPDATE ON public.parcel_requests FOR EACH ROW%'
  ) THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: trigger parcel_requests_before_write is missing, disabled or not wired to this function';
  END IF;

  -- EXECUTE must not be granted to PUBLIC / anon / authenticated.
  IF EXISTS (
    SELECT 1
      FROM pg_proc p, LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) AS a
     WHERE p.oid = v_oid AND a.privilege_type = 'EXECUTE'
       AND (a.grantee = 0 OR a.grantee IN (SELECT r.oid FROM pg_roles r WHERE r.rolname IN ('anon', 'authenticated')))
  ) THEN
    RAISE EXCEPTION 'parcel_01b_rollback_preflight: EXECUTE is granted to PUBLIC / anon / authenticated';
  END IF;
END
$parcel_01b_rollback_preflight$;

-- ─── Restore the exact Production source (verified before use) ───────────────────────────────────────
DO $parcel_01b_rollback_restore$
DECLARE
  v_src text := convert_from(decode(
    '',
    'hex'), 'UTF8');
BEGIN
  IF md5(v_src) <> 'caecf3a8dfcf97889ba246d77add0fac' OR length(v_src) <> 4862 THEN
    RAISE EXCEPTION 'parcel_01b_rollback_restore: embedded source failed verification (md5 %, length %)', md5(v_src), length(v_src);
  END IF;
  EXECUTE format(
    'CREATE OR REPLACE FUNCTION public.parcel_requests_before_write() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = %L AS %L',
    '', v_src);
END
$parcel_01b_rollback_restore$;

-- ─── Post-check: exact Production source restored, identity / config / trigger / ACL intact ───────────
DO $parcel_01b_rollback_postcheck$
DECLARE
  v_count  integer;
  v_oid    oid;
  v_result text;
  v_lang   text;
  v_secdef boolean;
  v_cfg    text[];
  v_md5    text;
  v_len    integer;
BEGIN
  SELECT count(*) INTO v_count
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'parcel_requests_before_write';
  IF v_count <> 1 THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: expected exactly one public.parcel_requests_before_write, found %', v_count;
  END IF;

  SELECT p.oid, pg_get_function_result(p.oid), l.lanname, p.prosecdef, p.proconfig, md5(p.prosrc), length(p.prosrc)
    INTO v_oid, v_result, v_lang, v_secdef, v_cfg, v_md5, v_len
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language l ON l.oid = p.prolang
   WHERE n.nspname = 'public' AND p.proname = 'parcel_requests_before_write';

  IF pg_get_function_identity_arguments(v_oid) <> '' OR v_result <> 'trigger' OR v_lang <> 'plpgsql' THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: unexpected signature / language (args=%, result=%, lang=%)',
      pg_get_function_identity_arguments(v_oid), v_result, v_lang;
  END IF;
  IF v_secdef THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: function is SECURITY DEFINER (expected INVOKER)';
  END IF;
  IF v_cfg IS DISTINCT FROM ARRAY['search_path=""'] THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: unexpected function configuration %', v_cfg;
  END IF;
  IF NOT ((v_md5 = 'caecf3a8dfcf97889ba246d77add0fac' AND v_len = 4862)) THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: restored source does not match the verified Production version (md5 %, length %)', v_md5, v_len;
  END IF;

  -- The existing trigger must keep calling this exact function, enabled, as BEFORE INSERT OR UPDATE ... FOR EACH ROW.
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
     WHERE t.tgrelid = to_regclass('public.parcel_requests')
       AND t.tgname = 'parcel_requests_before_write'
       AND NOT t.tgisinternal
       AND t.tgfoid = v_oid
       AND t.tgenabled <> 'D'
       AND pg_get_triggerdef(t.oid) ILIKE '%BEFORE INSERT OR UPDATE ON public.parcel_requests FOR EACH ROW%'
  ) THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: trigger parcel_requests_before_write is missing, disabled or not wired to this function';
  END IF;

  -- EXECUTE must not be granted to PUBLIC / anon / authenticated.
  IF EXISTS (
    SELECT 1
      FROM pg_proc p, LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) AS a
     WHERE p.oid = v_oid AND a.privilege_type = 'EXECUTE'
       AND (a.grantee = 0 OR a.grantee IN (SELECT r.oid FROM pg_roles r WHERE r.rolname IN ('anon', 'authenticated')))
  ) THEN
    RAISE EXCEPTION 'parcel_01b_rollback_postcheck: EXECUTE is granted to PUBLIC / anon / authenticated';
  END IF;
END
$parcel_01b_rollback_postcheck$;

COMMIT;
